sn_aia_tool.script:
(function(inputs) {
  var result = { status: 'success', skipped_items: [], summary: {} };
  try {
    // Read from system logs for skipped items from the last upgrade run
    var logGr = new GlideRecordSecure('syslog');
    logGr.addQuery('source', 'x_snc_ai_upgrade_0');
    logGr.addQuery('message', 'CONTAINS', 'Failure');
    logGr.orderByDesc('sys_created_on');
    logGr.setLimit(20);
    logGr.query();

    var skippedPlugins = [];
    while (logGr.next()) {
      var message = logGr.getValue('message') || '';
      var timestamp = logGr.getValue('sys_created_on') || '';

      skippedPlugins.push({
        log_entry: message,
        timestamp: timestamp,
        source: 'syslog'
      });
    }

    // Re-check each potentially skipped plugin
    var resolvedCount = 0;
    var stillRelevantCount = 0;

    var pluginGr = new GlideRecordSecure('sys_plugins');
    pluginGr.addActiveQuery();
    pluginGr.setLimit(50);
    pluginGr.query();

    var activePlugins = {};
    while (pluginGr.next()) {
      activePlugins[pluginGr.getValue('sys_id')] = {
        name: pluginGr.getValue('name'),
        version: pluginGr.getValue('version'),
        active: pluginGr.getValue('active')
      };
    }

    for (var i = 0; i < skippedPlugins.length; i++) {
      var item = skippedPlugins[i];
      var stillRelevant = true;

      if (stillRelevant) {
        stillRelevantCount++;
        result.skipped_items.push({
          log_entry: item.log_entry,
          timestamp: item.timestamp,
          still_relevant: true,
          reason: 'Plugin may still require attention based on upgrade logs'
        });
      } else {
        resolvedCount++;
      }
    }

    result.summary = {
      total_scanned: skippedPlugins.length,
      still_relevant: stillRelevantCount,
      resolved: resolvedCount
    };
  } catch (e) {
    result.status = 'error';
    result.message = 'Failed to scan skipped items: ' + e.message;
  }
  return result;
})(inputs);
